 * Name: bk7258_configure
 *
 * Description: Configure the audio device for the specified mode of
 *              operation.
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR void *session,
                            FAR const struct audio_caps_s *caps)
#else
static int bk7258_configure(FAR struct audio_lowerhalf_s *dev,
                            FAR const struct audio_caps_s *caps)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  int ret = OK;

  AUD_INFO("configure ac_type=%d", caps->ac_type);

  /* Create message queue if not yet created */

  if (priv->mqname[0] == '\0')
    {
      struct mq_attr attr;

      snprintf(priv->mqname, sizeof(priv->mqname), "/tmp/bk7258_%p",
               priv);

      attr.mq_maxmsg  = BK7258_AUDIO_MSG_MAX;
      attr.mq_msgsize = sizeof(struct audio_msg_s);
      attr.mq_curmsgs = 0;
      attr.mq_flags   = 0;

      ret = file_mq_open(&priv->mq, priv->mqname,
                         O_RDWR | O_CREAT, 0644, &attr);
      if (ret < 0)
        {
          AUD_ERR("Failed to create message queue: %d", ret);
          return ret;
        }
    }

  switch (caps->ac_type)
    {
      case AUDIO_TYPE_OUTPUT:
      case AUDIO_TYPE_INPUT:
        {
          /* Extract configuration from capabilities */

          priv->sample_rate = caps->ac_controls.hw[0] |
                              ((uint32_t)caps->ac_controls.b[3] << 16);
          priv->channels = caps->ac_channels;
          priv->bpsamp = caps->ac_controls.b[2];

          /* Default to 16-bit if not specified */

          if (priv->bpsamp == 0)
            {
              priv->bpsamp = 16;
            }

          /* Default to 16kHz if not specified */

          if (priv->sample_rate == 0)
            {
              priv->sample_rate = 16000;
            }

          /* Default to 2 channels if not specified */

          if (priv->channels == 0)
            {
              priv->channels = 2;
            }

          AUD_INFO("Configured: rate=%"PRIu32" ch=%d bps=%d",
                   priv->sample_rate, priv->channels, priv->bpsamp);
        }
        break;

      default:
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: bk7258_shutdown
 *
 * Description: Shutdown the driver and put it in the lowest power state.
 *
 ****************************************************************************/

static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;

  AUD_INFO("shutdown");

  /* Close message queue if open */

  if (priv->mqname[0] != '\0')
    {
      file_mq_close(&priv->mq);
      file_mq_unlink(priv->mqname);
      priv->mqname[0] = '\0';
    }

  return OK;
}

/****************************************************************************
 * Name: bk7258_start
 *
 * Description: Start the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
                        FAR void *session)
#else
static int bk7258_start(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  FAR char *argv[2];
  char arg1[32];
  int ret;

  AUD_INFO("start");

  if (priv->running)
    {
      AUD_ERR("Already running");
      return -EPERM;
    }

  priv->terminate = false;
  priv->running = true;

  /* Start worker thread */

  AUD_INFO("Starting worker thread");

  snprintf(arg1, sizeof(arg1), "%p", priv);
  argv[0] = arg1;
  argv[1] = NULL;

  ret = kthread_create("bk7258_audio",
                       BK7258_AUDIO_WORKER_PRIORITY,
                       BK7258_AUDIO_WORKER_STACKSIZE,
                       bk7258_worker_thread, argv);
  if (ret < 0)
    {
      AUD_ERR("Failed to create worker thread: %d", ret);
      priv->running = false;
      return ret;
    }

  priv->worker_pid = ret;
  AUD_INFO("Worker thread started (pid=%d)", ret);

  return OK;
}

/****************************************************************************
 * Name: bk7258_stop
 *
 * Description: Stop the configured operation (audio streaming).
 *
 ****************************************************************************/

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#ifdef CONFIG_AUDIO_MULTI_SESSION
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
                       FAR void *session)
#else
static int bk7258_stop(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  struct audio_msg_s term_msg;

  AUD_INFO("stop");

  if (!priv->running)
    {
      return OK;
    }

  /* Send stop message to worker thread */

  priv->terminate = true;

  term_msg.msg_id = AUDIO_MSG_STOP;
  term_msg.u.data = 0;

  file_mq_send(&priv->mq, (FAR const char *)&term_msg, sizeof(term_msg),
               BK7258_AUDIO_MSG_PRIO);

  /* Wait for worker thread to finish (with timeout) */

  int timeout = 50;
  while (priv->running && timeout-- > 0)
    {
      nxsig_usleep(10000);  /* 10ms */
    }

  /* Force cleanup if thread didn't exit */

  if (priv->running)
    {
      AUD_ERR("Worker thread did not exit, forcing cleanup");
      priv->running = false;
    }

  AUD_INFO("stop complete");

  return OK;
}
#endif

/****************************************************************************
 * Name: bk7258_enqueuebuffer
