/****************************************************************************
 * Name: bk7258_audio_playback_initialize
 *
 * Description:
 *   Initialize and register the BK7258 playback audio device as
 *   /dev/audio/pcm0p
 *
 ****************************************************************************/

int bk7258_audio_playback_initialize(void)
{
  FAR struct bk7258_audio_s *priv;
  int ret;

  syslog(LOG_INFO, "BK7258: Initializing playback device\n");

  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
  if (!priv)
    {
      syslog(LOG_ERR, "BK7258: Failed to allocate playback device\n");
      return -ENOMEM;
    }

  syslog(LOG_INFO, "BK7258: Allocated priv=%p, size=%d\n",
         priv, sizeof(struct bk7258_audio_s));

  priv->dev.ops = &g_bk7258_playback_ops;
  priv->type = BK7258_AUDIO_TYPE_PLAYBACK;
  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
  priv->channels = BK7258_AUDIO_DEFAULT_CHANNELS;
  priv->bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
  priv->gain = BK7258_AUDIO_DEFAULT_GAIN;
  priv->running = false;
  priv->terminate = false;
  priv->mqname[0] = '\0';

  syslog(LOG_INFO, "BK7258: Calling audio_register(pcm0p, %p)\n",
         &priv->dev);

  ret = audio_register("pcm0p", &priv->dev);
  if (ret < 0)
    {
      syslog(LOG_ERR, "BK7258: audio_register failed: %d\n", ret);
      kmm_free(priv);
      return ret;
    }

  syslog(LOG_INFO, "BK7258: Playback device registered OK\n");
  return OK;
}

/****************************************************************************
 * Name: bk7258_audio_capture_initialize
 *
 * Description:
 *   Initialize and register the BK7258 capture audio device as
 *   /dev/audio/pcm0c
 *
 ****************************************************************************/

int bk7258_audio_capture_initialize(void)
{
  FAR struct bk7258_audio_s *priv;
  int ret;

  AUD_INFO("Initializing capture device");

  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
  if (!priv)
    {
      AUD_ERR("Failed to allocate capture device");
      return -ENOMEM;
    }

  priv->dev.ops = &g_bk7258_capture_ops;
  priv->type = BK7258_AUDIO_TYPE_CAPTURE;
  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
  priv->channels = BK7258_AUDIO_DEFAULT_CHANNELS;
  priv->bpsamp = BK7258_AUDIO_DEFAULT_BPSAMP;
  priv->gain = BK7258_AUDIO_DEFAULT_GAIN;
  priv->running = false;
  priv->terminate = false;
  priv->mqname[0] = '\0';

  ret = audio_register("pcm0c", &priv->dev);
  if (ret < 0)
    {
      AUD_ERR("Failed to register capture device: %d", ret);
      kmm_free(priv);
      return ret;
    }

  AUD_INFO("Capture device registered as /dev/audio/pcm0c");
  return OK;
}

