  int ret = bk7258_rptun_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[AMP] CP RPTUN init failed: %d\n", ret);
    }
  else
    {
      syslog(LOG_INFO, "[AMP] CP RPTUN master initialized (Mailbox IRQ)\n");
