+                << DMA_CTRL_SRC_WIDTH_SHIFT;
+  ctrl |= ((uint32_t)cfg->dst_width & DMA_CTRL_WIDTH_MASK)
+                << DMA_CTRL_DST_WIDTH_SHIFT;
+  ctrl |= (units & 0xFFFFu) << DMA_CTRL_TRANSFER_LEN_SHIFT;
+  putreg32(ctrl, DMA_CH_CTRL(ch));
