+ *   bk7258_pcm [-r rate] [-c channels] [-f freq_hz] [-d duration_ms]
+ *              [-v volume]
+ *
+ * Defaults: 48 kHz, stereo, 1 kHz sine, 2000 ms, volume 80.
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#include <sys/ioctl.h>
+#include <sys/types.h>
+
+#include <errno.h>
+#include <fcntl.h>
+#include <math.h>
+#include <mqueue.h>
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <unistd.h>
+
+#include <nuttx/audio/audio.h>
