+      fill_sine((FAR int16_t *)apb->samp, chunk / 2, &phase);
+      apb->nbytes    = chunk;
+      apb->curbyte   = 0;
+      apb->nmaxbytes = buf_info.buffer_size;
+      bytes_written += chunk;
